import java.util.*;

class Solution {
    private Integer[] memo;

    public int tribonacci(int n) {
        memo = new Integer[n + 1];
        return solve(n);
    }

    private int solve(int n) {
        if (n == 0) return 0;
        if (n == 1 || n == 2) return 1;
        if (memo[n] != null) return memo[n];
        memo[n] = solve(n - 1) + solve(n - 2) + solve(n - 3);
        return memo[n];
    }
}
